create table if not exists profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text, phone text, role text not null default 'traveler' check (role in ('traveler','host','admin')), created_at timestamptz default now());
create table if not exists hosts (id uuid primary key default gen_random_uuid(), user_id uuid not null references profiles(id), business_name text, contact_name text, phone text, line_id text, package text not null default 'standard' check (package in ('standard','premium')), package_price numeric not null default 99, status text not null default 'pending' check (status in ('pending','approved','suspended')), created_at timestamptz default now());
create table if not exists listings (id uuid primary key default gen_random_uuid(), host_id uuid not null references hosts(id), name text not null, slug text unique not null, description text, location text not null, latitude numeric, longitude numeric, price numeric, price_unit text, capacity integer, category text, vibe text[], amenities text[], pet_friendly boolean default false, party_friendly boolean default false, tier text not null default 'standard' check (tier in ('standard','premium')), status text not null default 'draft' check (status in ('draft','pending','published','rejected')), created_at timestamptz default now());
create table if not exists listing_images (id uuid primary key default gen_random_uuid(), listing_id uuid not null references listings(id) on delete cascade, url text not null, sort_order integer default 0);
create table if not exists trip_sessions (id uuid primary key default gen_random_uuid(), user_id uuid references profiles(id), raw_input text, guests integer, budget numeric, destination text, vibe text[], preferences jsonb, result jsonb, created_at timestamptz default now());
create table if not exists leads (id uuid primary key default gen_random_uuid(), listing_id uuid references listings(id), user_id uuid references profiles(id), source text, contact_method text, status text default 'new' check(status in ('new','contacted','converted','lost')), created_at timestamptz default now());
create table if not exists listing_events (id bigint generated always as identity primary key, listing_id uuid references listings(id), event_type text not null, session_id uuid, metadata jsonb, created_at timestamptz default now());
